#include <iostream>
int main() {
    int x;
    if (!(std::cin >> x)) { std::cout << "invalid\n"; return 0; }
    if (x % 2 == 0) std::cout << "even\n";
    else std::cout << "odd\n";
}

#include <iostream>
int main() {
    int x;
    if (!(std::cin >> x)) { std::cout << "invalid\n"; return 0; }
    if (x < 0) std::cout << "negative\n";
    else if (x == 0) std::cout << "zero\n";
    else std::cout << "positive\n";
}

